    "clinicalCase": "Puérpera, 21 anos, é acolhida Unidade Básica de Saúde, após o nascimento da filha, há dez dias. Relata que pensa em entregar a filha para a avó cuidar, uma vez que se sente “sugada” pela recém-nascida, e sente momentos de tristeza ao longo do dia, quando se questiona se deveria ter engravidado ou não, desejando interromper a amamentação, voltar a trabalhar e, principalmente, não estar com a filha. Sente-se muito culpada por pensar dessa maneira e envergonhada por não conseguir ser uma “boa mãe”. Queixa-se também do sono, pois as noites maldormidas a deixam mais irritada. Está ainda mais preocupada, pois nunca se sentiu assim. Qual é a conduta mais adequada para esse caso?",
